message.content:
{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A map is unrolled at the edge of the ruined city.",
      "visual_description": "Mara crouches on a cracked cobblestone hill, brass compass spinning, an ink-stained map fluttering across broken statues; the skyline of the fallen royal city glows behind her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp wakes with a warning.",
      "visual_description": "A battered oil lamp held aloft in Mara's hand, its single flame-eye flaring orange, casting long shadows across rubble and torn banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "A clockwork scout is wound to life.",
      "visual_description": "Mara turns the key on a small tin fox; blue glass eyes blink awake, gears ticking, tail spinning under moonlight on a moss-grown plaza.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "A diver steps from a shattered window.",
      "visual_description": "The glass diver emerges from a tall broken pane like it were water, clear helmet fogged, coat reflecting fractured city lights and torchfire.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The rescuers approach the great gates.",
      "visual_description": "Massive iron castle gates loom, half-fallen and chained; the tin fox sniffs at a gap while the oracle lamp's flame leans sharply, pointing the way.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol stomps past in the fog.",
      "visual_description": "Silhouettes of empty armored suits clank down a narrow lane; the glass diver and Mara press flat into a doorway as the tin fox freezes, glass eyes dimmed.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Pale silhouettes hide behind shutters along a leaning street; Mara raises a calming hand while the oracle lamp dims its eye to a soft amber glow.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "A cursed tower whispers temptations.",
      "visual_description": "A spiral tower wreathed in violet smoke; glowing runes spell promises in the air. The oracle lamp's flame turns sharp blue in warning while Mara shields her eyes.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The tin fox finds a hidden side passage.",
      "visual_description": "The clockwork fox paws aside a torn royal banner revealing a crawl-hole beneath a collapsed arch; dust motes glitter in lamp light.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "They find the official asleep on his ledger.",
      "visual_description": "In a half-collapsed records office, the sleeping tax collector snores on a thick ledger, stamped papers stuck to his sleeves and ink pooling near his cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The lamp demands he wake; he does not.",
      "visual_description": "Oracle lamp thrust close to the sleeping tax collector's face, flame-eye glaring; he merely shifts and pulls a stamped paper over his head like a blanket.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "Rumors of a vast winged beast rumble overhead.",
      "visual_description": "An enormous shadow with wide wings passes across the broken moon; Mara and the glass diver duck beneath a fallen arch as scales of dust rain down.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door bars the inner courtyard.",
      "visual_description": "A tall door of swirling silver glyphs blocks an ivy-choked archway; the tin fox traces a glyph with its paw while the oracle lamp reads the door aloud.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The diver slips through the door's mirrored surface.",
      "visual_description": "The glass diver dives headfirst into the silver door as if into still water, ripples spreading; his coat trails reflections of the ruined skyline.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The official is hauled out, still snoring.",
      "visual_description": "Glass diver carries the limp sleeping tax collector over one shoulder; ledger thumping against his back, stamped papers fluttering loose like leaves.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge on the plaza.",
      "visual_description": "Hollow armored figures pour from three streets at once, halberds raised; the tin fox darts between their legs as Mara waves the others toward an alley.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint for the cracked stone bridge.",
      "visual_description": "A long arched bridge over a black ravine, torch sconces guttering; the rescue party runs across as flagstones crumble behind them into the dark below.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "On the far side, the lamp's eye finally softens.",
      "visual_description": "Beyond the bridge, dawn light bleeds over hills; Mara sets the oracle lamp on a stone, the tin fox curls at her feet, the glass diver lowers his helmet as the sleeping tax collector keeps right on snoring.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver", "sleeping_tax_collector"]
    }
  ]
}

